import{_ as a,o,c as r,a5 as t}from"./chunks/framework.CXvGqWf0.js";const p=JSON.parse('{"title":"漫画 · 第 38 话 Speculation Rules：点击前页面已备好","description":"","frontmatter":{},"headers":[],"relativePath":"comics/html/EP.38-speculation-rules.md","filePath":"comics/html/EP.38-speculation-rules.md","lastUpdated":1793421609000}'),l={name:"comics/html/EP.38-speculation-rules.md"};function c(s,e,d,i,n,u){return o(),r("div",null,[...e[0]||(e[0]=[t('<h1 id="漫画-·-第-38-话-speculation-rules-点击前页面已备好" tabindex="-1">漫画 · 第 38 话 Speculation Rules：点击前页面已备好 <a class="header-anchor" href="#漫画-·-第-38-话-speculation-rules-点击前页面已备好" aria-label="Permalink to &quot;漫画 · 第 38 话 Speculation Rules：点击前页面已备好&quot;">​</a></h1><blockquote><p>对应正文：<a href="./../../docs/html/13-speculation-rules">docs/html/13-speculation-rules.md</a> ｜ 原画：<a href="./EP.38-speculation-rules.svg">EP.38-speculation-rules.svg</a></p></blockquote><h2 id="登场角色" tabindex="-1">登场角色 <a class="header-anchor" href="#登场角色" aria-label="Permalink to &quot;登场角色&quot;">​</a></h2><ul><li><strong>像素酱</strong>：CSS 造型师，本话主角。被 MPA 站点「点击后白屏等待」折磨：DNS→TCP→TLS→TTFB→解析→渲染，LCP 500ms+，用户流失率飙升。</li><li><strong>标签君</strong>：HTML5 结构师，搬出 Speculation Rules 双件套——<code>prerender</code> 后台完整渲染整页、<code>document_rule</code> 自动探测可视区链接并按 <code>eagerness</code> 三档控制触发时机。</li></ul><h2 id="剧情梗概" tabindex="-1">剧情梗概 <a class="header-anchor" href="#剧情梗概" aria-label="Permalink to &quot;剧情梗概&quot;">​</a></h2><p>像素酱发现 <code>rel=&quot;prefetch&quot;</code> 只下载 HTML 文档，JS 不执行、图片不下载，用户感知仍是「加载中」。标签君引入 <code>&lt;script type=&quot;speculationrules&quot;&gt;</code>：<code>prerender</code> 在隐藏进程中完整渲染下一页（含 JS/CSS/图片），点击激活时 LCP ≈ 0ms；<code>document_rule</code> 自动探测可视区链接，无需维护 URL 列表；<code>eagerness</code> 三档（conservative/moderate/eager）平衡速度与资源消耗。配合 View Transitions 跨页转场，纯 MPA 架构获得超越多数 SPA 的导航体验。</p><h2 id="分格解读" tabindex="-1">分格解读 <a class="header-anchor" href="#分格解读" aria-label="Permalink to &quot;分格解读&quot;">​</a></h2><h3 id="格1-·-痛点现场" tabindex="-1">格1 · 痛点现场 <a class="header-anchor" href="#格1-·-痛点现场" aria-label="Permalink to &quot;格1 · 痛点现场&quot;">​</a></h3><p>MPA 导航等待链：click → DNS → TCP → TLS → TTFB → 解析 → 渲染 → LCP 500ms+。<code>rel=&quot;prefetch&quot;</code> 只拉文档，JS 不执行、图片不下载，感知仍是加载中。不知道用户会点哪个链接，全站 prefetch 浪费带宽；SPA 框架太重不想引入。</p><h3 id="格2-·-机制登场" tabindex="-1">格2 · 机制登场 <a class="header-anchor" href="#格2-·-机制登场" aria-label="Permalink to &quot;格2 · 机制登场&quot;">​</a></h3><p>推测规则双件套：<code>prerender</code> 预渲染（<code>&lt;script type=&quot;speculationrules&quot;&gt;</code> 配置 list 或 document 规则，后台在隐藏进程中完整渲染整页，JS/CSS/图片全部就绪，点击激活 LCP ≈ 0ms）、<code>document_rule</code> 自动探测（<code>href_matches</code> 匹配 URL 模式 + <code>eagerness</code> 三档控制触发时机，<code>moderate</code> 在链接进入可视区时触发）。</p><h3 id="格3-·-落地收束" tabindex="-1">格3 · 落地收束 <a class="header-anchor" href="#格3-·-落地收束" aria-label="Permalink to &quot;格3 · 落地收束&quot;">​</a></h3><p>四大实战场景：电商商品列表（document_rule + moderate，卡片进入可视区即预渲染）、博客「下一篇」（prefetch + list rule，仅预获取 HTML 降低 TTFB）、eagerness 三档对比（conservative=hover 触发、moderate=可视区触发、eager=加载完立即触发）、与 View Transitions 配合（prerender 让页面已渲染 + VT 让切换有动画，MPA 超越 SPA）。Chrome 123+ 独占，Safari/Firefox 渐进增强。</p><h2 id="码叔划重点" tabindex="-1">码叔划重点 <a class="header-anchor" href="#码叔划重点" aria-label="Permalink to &quot;码叔划重点&quot;">​</a></h2><ol><li><code>prerender</code> 后台完整渲染整页（JS/CSS/图片），点击激活 LCP ≈ 0ms。</li><li><code>document_rule</code> 自动探测可视区链接；<code>eagerness</code> 三档控触发时机，全站推荐 moderate。</li><li>敏感页面必须排除；需 localhost/https；与 View Transitions 配合实现瞬时导航 + 动画。</li></ol><h2 id="自测一题" tabindex="-1">自测一题 <a class="header-anchor" href="#自测一题" aria-label="Permalink to &quot;自测一题&quot;">​</a></h2><p><strong>问</strong>：<code>eagerness: eager</code> 与 <code>eagerness: moderate</code> 的区别是什么？全站使用 eager 有什么问题？</p><p><strong>答</strong>：<code>eager</code> 在页面加载完立即预渲染所有匹配链接，资源消耗巨大；<code>moderate</code> 在链接进入可视区时才触发，更平衡。全站用 eager 会同时启动大量隐藏渲染进程，内存和电量消耗激增，移动端尤其危险。</p><h2 id="动手实验" tabindex="-1">动手实验 <a class="header-anchor" href="#动手实验" aria-label="Permalink to &quot;动手实验&quot;">​</a></h2><ul><li>list rule 预获取 + document_rule 自动链接预渲染 + eagerness 三档对比 + prerender 状态检测：<a href="./../../examples/html/13-speculation-rules/index-01-speculation-rules.html">examples/html/13-speculation-rules/</a></li></ul><h2 id="下一话预告" tabindex="-1">下一话预告 <a class="header-anchor" href="#下一话预告" aria-label="Permalink to &quot;下一话预告&quot;">​</a></h2><p>敬请期待下一批次——更多前沿 CSS / HTML 特性持续解锁中！</p>',22)])])}const m=a(l,[["render",c]]);export{p as __pageData,m as default};
